-- TitanGlobal ERP: expedientes de importación (módulo 16, spec modulo16-importaciones-backend).
--
-- Un expediente sigue un embarque de una orden de abastecimiento: Incoterm, medio de transporte, fechas y estado
-- (Programado, EnTransito, EnAduana, Liberado, Cancelado). Una orden puede tener varios expedientes (embarques parciales).
-- Las reglas CK_ repiten en la base lo que ya valida la API, como segunda defensa ante datos cargados por fuera.
-- Convención de nombres: CK_<Tabla>_<Regla>.

CREATE TABLE "ExpedientesImportacion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "OrdenAbastecimientoId" integer NOT NULL,
    "Incoterm" character varying(3) NOT NULL,
    "MedioTransporte" character varying(20) NOT NULL,
    "PaisOrigen" character varying(100) NOT NULL,
    "LugarOrigen" character varying(100) NOT NULL,
    "LugarDestino" character varying(100) NOT NULL,
    "DocumentoTransporte" character varying(40),
    "FechaEmbarque" date,
    "FechaLlegadaEstimada" date NOT NULL,
    "FechaLlegadaReal" date,
    "Estado" character varying(20) NOT NULL,
    "MotivoCancelacion" character varying(500),
    "Observaciones" character varying(500),
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ExpedientesImportacion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ExpedientesImportacion_OrdenesAbastecimiento_OrdenAbastecimientoId" FOREIGN KEY ("OrdenAbastecimientoId") REFERENCES "OrdenesAbastecimiento" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ExpedientesImportacion_Incoterm" CHECK ("Incoterm" IN ('EXW', 'FCA', 'FAS', 'FOB', 'CFR', 'CIF', 'CPT', 'CIP', 'DAP', 'DPU', 'DDP')),
    CONSTRAINT "CK_ExpedientesImportacion_MedioTransporte" CHECK ("MedioTransporte" IN ('Maritimo', 'Aereo', 'Terrestre')),
    CONSTRAINT "CK_ExpedientesImportacion_Estado" CHECK ("Estado" IN ('Programado', 'EnTransito', 'EnAduana', 'Liberado', 'Cancelado')),
    CONSTRAINT "CK_ExpedientesImportacion_LlegadaRealPosteriorEmbarque" CHECK (
        "FechaEmbarque" IS NULL OR "FechaLlegadaReal" IS NULL OR "FechaLlegadaReal" >= "FechaEmbarque")
);
CREATE UNIQUE INDEX "IX_ExpedientesImportacion_Numero" ON "ExpedientesImportacion" ("Numero");
CREATE INDEX "IX_ExpedientesImportacion_OrdenAbastecimientoId" ON "ExpedientesImportacion" ("OrdenAbastecimientoId");
